import {LIMITS,validPose,STORAGE} from './core.js';
export const PINS={base:6,lower:9,upper:10,gripper:11};
export const INITIALIZED={base:90,lower:90,upper:90,gripper:90};
export function greeting(line){const m=/^(READY|PONG),CUBELINK,v1\.5\.5,(SAFE|RECOVERY_REQUIRED),PARK_90_30_160_90,(CUR0|CUR4)(?:,JM1)?$/.exec(line);return m?{state:m[2],current:m[3],firmware:'1.5.5'}:null;}
export const hardwareStatus={enabled:true,physicalTested:false,reason:'USB 통합 시험판 · CubeLinkBridge v1.5.5 전용. 실제 로봇팔 방향·정지·파지는 검증 대기입니다.'};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function bounded(p,ms,message){let timer;try{return await Promise.race([p,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error(message)),ms);})]);}finally{clearTimeout(timer);}}
export class CubeLinkUSB{
 constructor({serial=globalThis.navigator?.serial,onChange=()=>{},onLine=()=>{},now=()=>Date.now(),wait=sleep,heartbeat=true}={}){Object.assign(this,{serial,onChange,onLine,now,wait,useHeartbeat:heartbeat});this.state='disconnected';this.epoch=0;this.session=0;this.queue=Promise.resolve();this.waiters=new Set();this.pose={...INITIALIZED};this.distance=null;this.distanceAt=0;this.teach=new Map();serial?.addEventListener?.('disconnect',e=>{if(e.target===this.port||e.port===this.port)this.fault('USB 연결이 끊어졌습니다.');});}
 get ready(){return this.state==='ready';}
 setState(state,message=''){this.state=state;this.message=message;this.onChange(this);}
 waitLine(test,ms=5000){let timer,entry;const promise=new Promise((resolve,reject)=>{entry={test,resolve:v=>{clearTimeout(timer);this.waiters.delete(entry);resolve(v);},reject:e=>{clearTimeout(timer);this.waiters.delete(entry);reject(e);}};this.waiters.add(entry);timer=setTimeout(()=>entry.reject(Error('펌웨어 응답 시간 초과')),ms);});promise.catch(()=>{});return promise;}
 rejectWaiters(message){for(const w of [...this.waiters])w.reject(Error(message));}
 receive(line){this.onLine('RX '+line);const hello=greeting(line);if(this.state==='verifying'&&!hello&&/^(READY|PONG),CUBELINK,/.test(line)){this.fault('연결한 펌웨어는 지원 규격과 다릅니다. CubeLinkBridge v1.5.5 및 저장자세 프로파일을 확인하세요.');return;}if(hello){this.lastPong=this.now();if(this.state==='verifying'){this.identity=hello;this.setState(hello.state==='SAFE'?'verified':'recovery',hello.state==='SAFE'?'펌웨어 확인 · 초기화 필요':'저장자세 확인 필요');}}
  const u=/^U,(-?\d+(?:\.\d+)?)$/.exec(line);if(u){const cm=Number(u[1]);this.distance=cm>0&&cm<=400?cm:null;this.distanceAt=this.distance===null?0:this.now();}
  if(line==='EMERGENCY_STOPPED'){this.epoch++;this.lastPong=this.now();this.setState('recovery','모터 해제 확인 · 저장자세 재확인이 필요합니다.');}
  if(/^ERR,|^FAULT,/.test(line)){this.fault('펌웨어 오류: '+line);return;}
  for(const w of [...this.waiters])if(w.test(line))w.resolve(line);this.onChange(this);
 }
 async readLoop(session){const decoder=new TextDecoder();let buffer='';try{while(session===this.session){const {value,done}=await this.reader.read();if(session!==this.session)return;if(done)break;buffer+=decoder.decode(value,{stream:true});if(buffer.length>8192)throw Error('시리얼 수신 길이 오류');let i;while((i=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,i).trim();buffer=buffer.slice(i+1);if(line)this.receive(line);}}if(session===this.session)this.fault('USB 수신이 종료되었습니다.');}catch(e){if(session===this.session)this.fault('USB 수신 실패: '+e.message);}}
 async connect(){if(!this.serial)throw Error('PC Chrome 또는 Edge에서 USB 시리얼을 사용하세요.');if(this.state!=='disconnected')throw Error('기존 연결을 먼저 해제하세요.');const s=++this.session;this.identity=null;this.teach.clear();this.distance=null;this.setState('opening','USB 장치를 선택하세요.');
  try{const port=await this.serial.requestPort();if(s!==this.session)throw Error('연결 취소');this.port=port;const opening=port.open({baudRate:115200,bufferSize:4096});opening.then(()=>{if(s!==this.session)port.close().catch(()=>{});},()=>{});await bounded(opening,8000,'USB 포트를 열지 못했습니다. 다른 앱의 연결을 종료하세요.');if(s!==this.session)throw Error('연결 취소');this.writer=port.writable.getWriter();this.reader=port.readable.getReader();this.queue=Promise.resolve();this.epoch++;this.setState('verifying','CubeLink v1.5.5 펌웨어 확인 중…');this.readTask=this.readLoop(s);const hello=this.waitLine(line=>!!greeting(line),7000);const probe=setInterval(()=>{if(this.state==='verifying')this.write('P').catch(()=>{});},700);try{await this.write('P');await hello;}finally{clearInterval(probe);}if(s!==this.session)throw Error('연결 종료');if(this.useHeartbeat)this.heartbeat=setInterval(()=>this.tick(),1000);
  }catch(e){await this.close(false);throw Error(e.name==='NotFoundError'?'USB 선택을 취소했습니다.':e.message);}
 }
 write(line){if(!this.writer)return Promise.reject(Error('USB 연결이 없습니다.'));if(!/^(P|R|I|K|X|S,(6|9|10|11),\d+)$/.test(line))return Promise.reject(Error('허용하지 않는 명령'));const motion=line.startsWith('S,');if(motion){const [,pin,angle]=line.split(',');const k=Object.keys(PINS).find(k=>PINS[k]===Number(pin));if(Number(angle)<LIMITS[k][0]||Number(angle)>LIMITS[k][1])return Promise.reject(Error('각도 제한 초과'));}if(motion&&!this.ready)return Promise.reject(Error('실물 초기화를 먼저 완료하세요.'));const epoch=this.epoch,session=this.session,writer=this.writer;
  const task=this.queue.then(async()=>{if(session!==this.session||epoch!==this.epoch)throw Error('취소된 USB 명령');if(motion&&!this.ready)throw Error('실물 실행 잠김');await bounded(writer.write(new TextEncoder().encode(line+'\n')),1500,'USB 쓰기 시간 초과');this.onLine('TX '+line);});this.queue=task.catch(()=>{});return task.catch(e=>{if(session===this.session&&epoch===this.epoch&&!e.message.startsWith('취소'))this.fault(e.message);throw e;});
 }
 tick(){if(!this.writer||!['verified','recovery','ready'].includes(this.state))return;if(this.now()-this.lastPong>4500){this.fault('펌웨어 응답이 끊겼습니다. 전원과 USB를 확인하세요.');return;}this.write('P').catch(()=>{});}
 async initialize(confirmed){if(!confirmed)throw Error('전원을 끈 상태에서 저장자세를 맞춘 뒤 확인해 주세요.');if(!['verified','recovery'].includes(this.state)||!this.identity)throw Error('지원되는 CubeLink 펌웨어를 먼저 연결하세요.');const recovery=this.state==='recovery';this.setState('initializing','한 관절씩 초기화 중 · 팔을 받쳐 주세요.');this.epoch++;
  try{if(recovery){const ack=this.waitLine(l=>l==='RECOVERY_ACCEPTED');await this.write('R');await ack;}const ack=this.waitLine(l=>l==='INIT_OK',20000);await this.write('I');await ack;if(this.state!=='initializing')throw Error('초기화 중단');this.pose={...INITIALIZED};this.lastPong=this.now();this.setState('ready','실물 준비 완료 · 명령 각도 표시');}catch(e){this.fault(e.message);throw e;}
 }
 sensor(){if(!this.ready)throw Error('실물 연결 준비 전입니다.');if(this.distance===null||this.now()-this.distanceAt>1500)throw Error('유효한 초음파 값이 없습니다. 센서 연결을 확인하세요.');return this.distance;}
 async moveTo(target,{onPose=()=>{}}={}){validPose(target);if(!this.ready)throw Error('실물 준비 완료 상태가 아닙니다.');if(this.moving)throw Error('다른 관절 이동이 진행 중입니다.');const epoch=this.epoch;this.moving=true;try{
  // One axis at a time, <=2 degrees per 40 ms; no implied collision planning.
  for(const k of ['upper','lower','base','gripper']){const start=this.pose[k],end=Math.round(target[k]),steps=Math.ceil(Math.abs(end-start)/2);for(let i=1;i<=steps;i++){if(epoch!==this.epoch||!this.ready)throw Error('실물 동작 중단');const angle=Math.round(start+(end-start)*i/steps);await this.write(`S,${PINS[k]},${angle}`);if(epoch!==this.epoch)throw Error('실물 동작 중단');this.pose={...this.pose,[k]:angle};onPose({...this.pose});await this.wait(40);}}}finally{this.moving=false;}
 }
 record(station,mode){if(!this.ready)throw Error('초기화 후 위치를 저장하세요.');if(!['A','B','C','D'].includes(station)||!['travel','pick','place'].includes(mode))throw Error('저장 위치 오류');this.teach.set(station+':'+mode,{...this.pose});this.onChange(this);}
 async emergency(){if(!this.identity||!this.writer)throw Error('확인된 USB 연결이 없습니다.');this.epoch++;this.rejectWaiters('정지 요청');this.setState('stopping','모터 해제 요청 · 팔을 받쳐 주세요.');const ack=this.waitLine(l=>l==='EMERGENCY_STOPPED',3000);try{await this.write('X');await ack;}catch(e){this.setState('fault','모터 해제 응답이 없습니다. 전원을 차단하세요.');throw e;}}
 fault(message){if(this.state==='disconnected'||this.state==='fault')return;const canStop=!!this.identity&&!!this.writer;this.epoch++;this.rejectWaiters(message);this.setState('fault',message);if(canStop)this.write('X').catch(()=>{});}
 async park(){if(!this.ready)throw Error('실물 준비 완료 상태에서 저장 종료하세요.');this.epoch++;this.setState('parking','펌웨어 저장자세 이동·모터 해제 중…');try{const ack=this.waitLine(l=>l==='PARKED',25000);await this.write('K');await ack;this.pose={...STORAGE};this.setState('verified','저장 종료 완료');}catch(e){this.fault(e.message);throw e;}}
 async close(safe=true){if(safe&&this.ready)await this.park();if(safe&&['initializing','parking','stopping'].includes(this.state))throw Error('동작 종료를 기다리거나 모터 해제를 누르세요.');this.session++;this.epoch++;clearInterval(this.heartbeat);this.rejectWaiters('USB 연결 종료');const reader=this.reader,writer=this.writer,port=this.port;this.reader=this.writer=this.port=null;try{await bounded(reader?.cancel(),1000,'수신 종료 시간 초과');}catch{}try{reader?.releaseLock();}catch{}try{await bounded(writer?.abort(),1000,'송신 종료 시간 초과');}catch{}try{writer?.releaseLock();}catch{}try{await bounded(port?.close(),1500,'포트 종료 시간 초과');}catch{}this.identity=null;this.teach.clear();this.queue=Promise.resolve();this.setState('disconnected','USB 연결 해제');}
}
